            var high = start.height
            if handle.isCorner {
                wide = start.width * Double(aspectFree ? axisX : diagonal)
                high = start.height * Double(aspectFree ? axisY : diagonal)
            } else if handle.drivesX {
                wide = start.width * Double(axisX)
